"""Postprocess scalar transient measurements generated by ngspice."""

OUTPUTS = (
    "vid_pp",
    "vod_pp",
    "vod_rms",
    "vocm_min",
    "vocm_max",
)


def postprocess(results, conditions):
    output = {}

    for name in OUTPUTS:
        raw_name = f"raw_{name}"

        if raw_name not in results:
            raise ValueError(
                f"Missing transient measurement: {raw_name}. "
                f"Available: {list(results)}"
            )

        values = results[raw_name]

        if not values:
            raise ValueError(f"Empty transient measurement: {raw_name}")

        output[name] = [float(value) for value in values]

    return output
